"use strict";(globalThis.webpackChunksap_architecture_center=globalThis.webpackChunksap_architecture_center||[]).push([[32813],{93218(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>o,default:()=>h,frontMatter:()=>s,metadata:()=>a,toc:()=>d});const a=JSON.parse('{"id":"north-star-arch/ai-native-northstar-arch/integration-security-ethics-governance/id-nsa-7","title":"Integration, Security, Ethics & Governance","description":"How SAP\'s AI-native architecture governs agents: a governed gateway, scoped agent identity, three-tier AI defense, and AI ethics review under the EU AI Act.","source":"@site/docs/north-star-arch/ai-native-northstar-arch/7-integration-security-ethics-governance/readme.md","sourceDirName":"north-star-arch/ai-native-northstar-arch/7-integration-security-ethics-governance","slug":"/ai-native-north-star-architecture/integration-security-ethics-governance","permalink":"/architecture-center/docs/ai-native-north-star-architecture/integration-security-ethics-governance","draft":false,"unlisted":false,"editUrl":"https://github.com/SAP/architecture-center/edit/dev/docs/north-star-arch/ai-native-northstar-arch/7-integration-security-ethics-governance/readme.md","tags":[{"inline":false,"label":"AI-native North Star architecture","permalink":"/architecture-center/docs/tags/ai-native-north-star","description":"The AI-native North Star architecture defines the target state of SAP\'s technology landscape. It is not a specification, roadmap, or promise of delivery. It is a direction of travel; a statement of how AI, data, processes, and the platform must work together as intelligence becomes the norm rather than an add-on."}],"version":"current","lastUpdatedBy":"SAP","lastUpdatedAt":1792713600000,"sidebarPosition":7,"frontMatter":{"id":"id-nsa-7","sidebar_position":7,"slug":"/ai-native-north-star-architecture/integration-security-ethics-governance","sidebar_custom_props":{"category_index":[]},"title":"Integration, Security, Ethics & Governance","description":"How SAP\'s AI-native architecture governs agents: a governed gateway, scoped agent identity, three-tier AI defense, and AI ethics review under the EU AI Act.","keywords":["sap","ai integration","governed gateway","agent identity","model context protocol","agent2agent protocol","three-tier ai defense architecture","zero-trust authentication","prompt injection detection","eu ai act","ai governance","ai ethics","sap global ai ethics policy","human-in-the-loop","north star architecture","business ai platform"],"sidebar_label":"7. Integration, Security, Ethics & Governance","image":"img/ac-soc-med.png","tags":["ai-native-north-star"],"hide_table_of_contents":false,"hide_title":false,"toc_min_heading_level":2,"toc_max_heading_level":4,"draft":false,"unlisted":false,"pagination_prev":"north-star-arch/ai-native-northstar-arch/platform-layer/id-nsa-6","pagination_next":"north-star-arch/ai-native-northstar-arch/ecosystem/id-nsa-8","contributors":null,"discussion":null,"last_update":{"author":"SAP","date":"2026-10-23T00:00:00.000Z"}},"sidebar":"northStarSidebar","previous":{"title":"6. Platform Layer","permalink":"/architecture-center/docs/ai-native-north-star-architecture/platform-layer"},"next":{"title":"8. Ecosystem","permalink":"/architecture-center/docs/ai-native-north-star-architecture/ecosystem"}}');var i=n(74848),r=n(28453);const s={id:"id-nsa-7",sidebar_position:7,slug:"/ai-native-north-star-architecture/integration-security-ethics-governance",sidebar_custom_props:{category_index:[]},title:"Integration, Security, Ethics & Governance",description:"How SAP's AI-native architecture governs agents: a governed gateway, scoped agent identity, three-tier AI defense, and AI ethics review under the EU AI Act.",keywords:["sap","ai integration","governed gateway","agent identity","model context protocol","agent2agent protocol","three-tier ai defense architecture","zero-trust authentication","prompt injection detection","eu ai act","ai governance","ai ethics","sap global ai ethics policy","human-in-the-loop","north star architecture","business ai platform"],sidebar_label:"7. Integration, Security, Ethics & Governance",image:"img/ac-soc-med.png",tags:["ai-native-north-star"],hide_table_of_contents:!1,hide_title:!1,toc_min_heading_level:2,toc_max_heading_level:4,draft:!1,unlisted:!1,pagination_prev:"north-star-arch/ai-native-northstar-arch/platform-layer/id-nsa-6",pagination_next:"north-star-arch/ai-native-northstar-arch/ecosystem/id-nsa-8",contributors:null,discussion:null,last_update:{author:"SAP",date:new Date("2026-10-23T00:00:00.000Z")}},o=void 0,c={},d=[{value:"Integration",id:"integration",level:2},{value:"SAP-Managed Integration",id:"sap-managed-integration",level:2},{value:"Security and agent identity",id:"security-and-agent-identity",level:2},{value:"AI ethics",id:"ai-ethics",level:2},{value:"Governance and compliance",id:"governance-and-compliance",level:2}];function l(e){const t={a:"a",h2:"h2",li:"li",p:"p",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:"Autonomous agents operate within enterprise-grade boundaries for governance, identity, and interoperability. Integration remains the biggest challenge in enterprise AI, and governance and compliance are not yet fully solved across industries. SAP is focusing on building architectural foundations that make these challenges tractable."}),"\n",(0,i.jsx)(t.h2,{id:"integration",children:"Integration"}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"AI enables integration"}),": Agents dynamically determine intent, select the right APIs, and orchestrate calls across systems. They learn from usage to improve quality over time, and they reduce environmental impact by removing redundant integration logic and minimizing avoidable system-to-system data transfers."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Integration enables AI"}),": Existing APIs, events, and data across SAP and third-party software systems become tools that agents can discover and use through open standards, without requiring new development artifacts. Two open protocols make this possible. The Model Context Protocol provides tool integration, enabling agents to discover and invoke capabilities across systems. The Agent2Agent protocol supports multiagent coordination, enabling agents built by different teams, partners, and customers to collaborate within governed boundaries. SAP participates in the open standards ecosystem to ensure agents interoperate across the enterprise landscape, not just within SAP."]}),"\n",(0,i.jsxs)(t.p,{children:["Thus, integration shifts from ",(0,i.jsx)(t.strong,{children:"connector-driven to intelligence-driven"}),"."]}),"\n",(0,i.jsx)(t.h2,{id:"sap-managed-integration",children:"SAP-Managed Integration"}),"\n",(0,i.jsx)(t.p,{children:"SAP's strategy is to deliver a pre-integrated, AI-native Autonomous Suite in which applications, AI agents, and assistants operate as a cohesive solution. SAP-managed provisioning, functional and technical integration, and lifecycle management enable agents to execute end-to-end business processes across applications, accelerating customer time to value and differentiating SAP from point-solution providers. Preconfigured integrations and shared business context enable agents to coordinate actions across the suite, while centralized governance, observability, automated safeguards, and SAP-managed operations support reliable, secure, and accountable execution. This reduces customer complexity and allows enterprises to focus on business outcomes rather than assembling and operating the underlying technology."}),"\n",(0,i.jsx)(t.p,{children:"Agent traffic flows through a governed gateway that acts as the trusted bridge between agents, tools, and backend systems. It ensures that agents operate within defined boundaries and are only accessible when explicitly authorized for collaboration \u2014 whether across systems, applications, or organizational domains. The gateway handles the platform-level concerns that every agent integration needs: security, access control, identity, and observability. It provides a unified catalog of available tools, enforces who can use what, and routes decisions that require human approval before proceeding. Backend systems are always accessed through official, governed APIs."}),"\n",(0,i.jsx)(t.h2,{id:"security-and-agent-identity",children:"Security and agent identity"}),"\n",(0,i.jsxs)(t.p,{children:["Agentic AI introduces new categories of risk that traditional security frameworks were not designed to address. Agents make autonomous decisions, access external tools, and operate across trust boundaries. Multiagent systems acting across organizations magnify these risks. Regulatory frameworks, including the ",(0,i.jsx)(t.strong,{children:"EU AI Act"})," and ",(0,i.jsx)(t.strong,{children:"US AI Action Plan"}),", make AI security mandatory. Trust is what converts capability into permission to act. Without it, agents can advise but cannot operate. With it, agents execute across real workflows, accumulate institutional judgment, and become more valuable with each interaction."]}),"\n",(0,i.jsxs)(t.p,{children:["In the AI-native model, ",(0,i.jsx)(t.strong,{children:"agents are first-class principals"}),": they authenticate, receive authorizations, and are governed like any other enterprise actor. Each agent carries its own identity that combines an application registration, policy assignments for persistent roles, and ",(0,i.jsx)(t.strong,{children:"scoped authorizations"}),". Users can grant agents a ",(0,i.jsx)(t.strong,{children:"bounded subset of their permissions"})," for unattended execution to make sure agents never act beyond their authorized scope. Alternatively, an agent can act in its own right, with scoped authorizations assigned specifically to it. When a system-triggered agent needs to act in a user's context, it requests this through a task in that user's inbox and continues with the user's permissions once the task is completed. Third-party agents must also authenticate via identity services from SAP; agents without valid credentials are denied access. When agents from SAP call into third-party systems, the platform performs ",(0,i.jsx)(t.strong,{children:"token exchanges"})," on their behalf to maintain governed access across trust boundaries."]}),"\n",(0,i.jsxs)(t.p,{children:["The ",(0,i.jsx)(t.strong,{children:"three-tier AI defense architecture"})," from SAP addresses agentic threats through a progressive approach:"]}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Foundation tier"}),": Zero-trust authentication, traffic inspection, prompt-injection detection, behavioral analytics, and cryptographically verifiable agent credentials. Entities are validated, and actions are recorded."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Supervision tier"}),": Deterministic control agents that monitor, sanitize, and authorize other AI agents. These supervisory agents enforce input validation, output filtering, and anomaly detection\u2014with human oversight for high-risk decisions."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Automation tier"}),": Specialized AI agents that scale security operations through continuous audits, risk assessment, and policy enforcement. Identity management agents handle provisioning and contextual authorization. This layer embeds secure development practices into AI-assisted workflows, helping ensure AI-generated code is validated and compliant before release."]}),"\n"]}),"\n",(0,i.jsxs)(t.p,{children:["AI is also an ally: intelligent agents audit systems, perform authorization checks, detect vulnerabilities, and enforce compliance early in development. This embeds a ",(0,i.jsx)(t.strong,{children:"shift-left approach"})," that prevents risks rather than reacting to them."]}),"\n",(0,i.jsx)(t.h2,{id:"ai-ethics",children:"AI ethics"}),"\n",(0,i.jsx)(t.p,{children:"As AI becomes embedded across the architecture, shaping how systems reason, act, and interact, AI ethics becomes a foundational cross-cutting concern across each layer. It works to ensure AI systems are designed, developed, deployed, used, and commercialized in line with defined standards of trust and responsibility. Agents introduce a distinct ethical risk profile because they can not only generate outputs but also plan, act, invoke tools, and operate across system and organizational boundaries with limited human intervention. Their autonomy, scale, and ability to affect real workflows increase the potential for unintended harm, unfair outcomes, opaque decision-making, and weakened accountability. SAP helps operationalize AI ethics through a global policy framework, structured use-case review, defined oversight structure, and lifecycle controls integrated with security, data protection, risk management, and compliance."}),"\n",(0,i.jsxs)(t.p,{children:["SAP\u2019s approach is anchored in the ",(0,i.jsx)(t.a,{href:"https://www.sap.com/products/artificial-intelligence/ai-ethics.html?pdf-asset=a8431b91-117e-0010-bca6-c68f7e60039b&page=1",children:"SAP Global AI Ethics Policy"}),", aligned with internationally recognized frameworks including UNESCO\u2019s Recommendation on the Ethics of Artificial Intelligence and the Organization for Economic Cooperation and Development (OECD) AI Principles. A defined oversight structure, supported by a dedicated AI ethics office, provides oversight, escalation paths, and accountability across the AI portfolio at SAP. An external advisory panel is consulted to deepen the understanding of broader ethical implications where necessary."]}),"\n",(0,i.jsx)(t.p,{children:"SAP applies a structured AI ethics impact assessment to classify use cases by risk and determine the appropriate review path. High-risk use cases are reviewed through defined governance bodies, with escalation to the AI ethics steering committee and, when broader implications arise, the Executive Board of SAP SE. When no ethically acceptable trade-off can be identified, the AI system cannot proceed in that form. Clear ethical principles, accountable oversight, and structured review define the boundaries within which agents can operate."}),"\n",(0,i.jsx)(t.h2,{id:"governance-and-compliance",children:"Governance and compliance"}),"\n",(0,i.jsxs)(t.p,{children:["SAP governs both internal AI use and AI delivered through its products to ensure regulatory compliance. All AI use cases undergo ",(0,i.jsx)(t.strong,{children:"risk classification"}),"; high-risk systems apply continuous monitoring, human oversight, data governance, and accuracy controls. Third-party components are governed through due diligence and ongoing compliance checks. SAP certifies its AI against international standards aligned with the International Organization for Standardization and the National Institute of Standards and Technology, supporting customers with the documentation required for their own compliance obligations."]}),"\n",(0,i.jsx)(t.p,{children:"With trust, integration, and governance in place, the AI-native enterprise opens beyond SAP."})]})}function h(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>o});var a=n(96540);const i={},r=a.createContext(i);function s(e){const t=a.useContext(r);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(r.Provider,{value:t},e.children)}}}]);